def _coerce_dict_chunking_config(value: dict[str, Any]) -> ChunkingConfig:
    """Coerce a dict into ChunkingConfig, converting nested types in-place."""
    _struct_coercions = {
        "embedding": _to_rust_embedding_config,
        "sparse_embedding": _to_rust_sparse_embedding_config,
        "late_interaction": _to_rust_late_interaction_config,
    }
    for _k, _fn in _struct_coercions.items():
        if _k in value and value[_k] is not None:
            value[_k] = _fn(value[_k])
    _enum_coercions = {
        "chunker_type": _rust.ChunkerType,
        "table_chunking": _rust.TableChunkingMode,
    }
    for _k, _cls in _enum_coercions.items():
        if _k in value and value[_k] is not None:
            value[_k] = _coerce_enum(_cls, value[_k])
    _data_enum_coercions = {
        "sizing": _rust.ChunkSizing,
    }
    for _k, _data_cls in _data_enum_coercions.items():
        if _k in value and value[_k] is not None and not isinstance(value[_k], _data_cls):
            value[_k] = _data_cls(value[_k])
    return ChunkingConfig(**value)


