def validate_iban(text: str) -> bool | None:
    """IBAN: ISO 13616 mod-97 check (remainder must be 1)."""
    return _rust.validate_iban(text=text)


def validate_us_ssn(text: str) -> bool | None:
    """US SSN: reject structurally-impossible numbers (area 000/666/9xx, group 00, serial 0000)."""
    return _rust.validate_us_ssn(text=text)


def validate_vin(text: str) -> bool | None:
    """VIN: 17 chars, ISO 3779 mod-11 check digit at position 9 (`X` == 10). North-American VINs."""
    return _rust.validate_vin(text=text)


def verify_entries(entries: list[AuditEntry]) -> None:
    """Recompute every chain hash in `entries` from genesis and report the first mismatch."""
    _rust.verify_entries(entries=entries)


def verify_key(candidate: str, stored_hash: str) -> bool:
    """Verify a candidate key against a stored Argon2id hash."""
    return _rust.verify_key(candidate=candidate, stored_hash=stored_hash)


def verify_seal_chain(seals: list[SegmentSeal]) -> None:
    """Verify a slice of [`SegmentSeal`]s from a single node, oldest first."""
    _rust.verify_seal_chain(seals=seals)


async def warm_embedding_preset(name: str) -> _rust.WarmResult:
    """Warm embedding preset."""
    return await _rust.warm_embedding_preset(name=name)
